\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\Z}{\mathbb{Z}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\Fp}{\mathbb{F}_p}
\newcommand{\Zp}{\mathbb{Z}_p}
\newcommand{\content}{\operatorname{content}}
\newcommand{\pp}{\operatorname{pp}}
\newcommand{\trdeg}{\operatorname{trdeg}}
\newcommand{\gtw}{\tau}
\newcommand{\shtw}{\tau^{\sharp}}
\newcommand{\fltw}{\tau^{\flat}}
\newcommand{\muI}{\mu_p}
\newcommand{\laI}{\lambda_p}

\title{An Algebraic Model of the Sharp/Flat $\lambda$-Difference under Quadratic
Twist as a $\mu$-Proportional Correction}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We construct a self-contained algebraic model of the two Iwasawa invariants
$\mu$ and $\lambda$ of a characteristic element, realized on the polynomial ring
$\Z[X]$, and use it to isolate the purely algebraic core of the extension of
Matsuno's quadratic-twist formula to the case of a non-vanishing
$\mu$-invariant. Modeling the $\mu$-invariant as the $p$-adic valuation of the
content (the gcd of the coefficients) and the $\lambda$-invariant as the trailing
degree of the mod-$p$ reduction of the primitive part, we prove that both
invariants are additive under multiplication: $\mu$ by Gauss's Lemma together
with additivity of the $p$-adic valuation, and $\lambda$ by additivity of the
trailing degree in the integral domain $\Fp[X]$. Building on this bridge, we
introduce a two-component \emph{sharp/flat} pair of twist factors sharing a
common $\mu$-depth but carrying distinct proportionality constants, and prove
that (i) the twist acts identically on the two $\mu$-invariants; (ii) the
resulting sharp/flat $\lambda$-difference is exactly a $\mu$-proportional term,
$\lambda^\sharp - \lambda^\flat = (c_\sharp - c_\flat)\,\mu$, valid over $\Z$
regardless of sign; and (iii) this difference is nonzero precisely when
$\mu \ne 0$ and $c_\sharp \ne c_\flat$. Finally, a generalized twist factor is
shown to realize every pair $(\lambda, \mu)$, so that the ratio $\lambda/\mu$ is
a free parameter.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Background and motivation}
Iwasawa theory studies arithmetic invariants of number fields and elliptic curves
by organizing them along an infinite tower of field extensions and packaging the
resulting data as modules over the \emph{Iwasawa algebra} $\Lambda = \Zp[[T]]$,
the ring of formal power series in one variable over the $p$-adic integers. A
finitely generated torsion $\Lambda$-module $M$ has a \emph{characteristic
element} $f \in \Lambda$, well defined up to a unit, whose two structural
invariants control the growth of $M$ up the tower:
\begin{itemize}
  \item the \textbf{$\mu$-invariant} $\muI(f)$, the $p$-adic valuation of $f$
        (the largest power of $p$ dividing all coefficients); and
  \item the \textbf{$\lambda$-invariant} $\laI(f)$, the degree of the
        distinguished polynomial supplied by the Weierstrass Preparation Theorem.
\end{itemize}
For an elliptic curve $E/\mathbb{Q}$ with good \emph{ordinary} reduction at $p$, a
single $p$-adic $L$-function governs the theory. At a \emph{supersingular} prime,
Pollack and Sprung showed that one attaches a \textbf{pair} of characteristic
elements --- a \emph{sharp} element $f^\sharp$ and a \emph{flat} element
$f^\flat$ --- related by a logarithmic (Pollack--Sprung) matrix.

A quadratic twist by a squarefree integer $D$ replaces $E$ by its twist $E_D$
and, on the level of characteristic elements, multiplies each by a \emph{twist
factor}. Matsuno's formula compares the $\lambda$-invariants of $E$ and $E_D$; in
its classical form it addresses the ubiquitous case $\mu = 0$. When $\mu \ne 0$,
the comparison is expected to acquire a correction term proportional to $\mu$.

\subsection{Contribution}
This paper isolates and rigorously establishes the purely algebraic \emph{core}
underlying the invariant bookkeeping of this story, in a fully elementary
setting. We (1) give a polynomial model of both invariants on $\Z[X]$ faithful to
the Weierstrass separation; (2) prove additivity of both invariants under
multiplication; and (3) build a faithful sharp/flat pair model and establish
$\mu$-symmetry, the $\mu$-proportional $\lambda$-difference, its sharp
non-vanishing, and a free $\lambda/\mu$ ratio.

\section{Preliminaries}
Throughout, $p$ is a fixed prime and polynomials have integer coefficients unless
noted. We write $C(a)$ for the constant polynomial with value $a$.

\textbf{Content and primitive part.} For nonzero $f \in \Z[X]$, the
\emph{content} $\content(f)$ is the (normalized nonnegative) gcd of the
coefficients of $f$, and the \emph{primitive part} $\pp(f)$ is the unique
polynomial with $f = \content(f)\cdot \pp(f)$, where $\pp(f)$ is
\emph{primitive}: the gcd of its coefficients is $1$.

\textbf{$p$-adic valuation.} For nonzero $n \in \Z$, $v_p(n)$ is the exponent of
$p$ in $n$; it is additive: $v_p(mn) = v_p(m) + v_p(n)$.

\textbf{Reduction mod $p$.} For $f \in \Z[X]$, write $\overline{f} \in \Fp[X]$
for the coefficientwise reduction modulo $p$. Reduction is a ring homomorphism.

\textbf{Trailing degree.} For nonzero $g$ over any ring, $\trdeg(g)$ is the
smallest $i$ with nonzero coefficient of $X^i$ (the multiplicity of $X$ as a
factor); $\trdeg(0) = 0$. In an integral domain, $\trdeg(gh) = \trdeg(g) +
\trdeg(h)$ for nonzero $g, h$.

\section{The invariants in the polynomial model}

\begin{definition}[Reduction]
For $f \in \Z[X]$, let $\overline{f} \in \Fp[X]$ be its coefficientwise reduction
modulo $p$.
\end{definition}

\begin{definition}[$\mu$-invariant]
For $f \in \Z[X]$ define $\muI(f) := v_p\big(\content(f)\big)$.
\end{definition}

\begin{definition}[$\lambda$-invariant]
For $f \in \Z[X]$ define $\laI(f) := \trdeg\big(\overline{\pp(f)}\big)$.
\end{definition}

These mirror the genuine invariants: writing $f = p^{\mu}\, u\, P(T)$ via
Weierstrass Preparation, with $u$ a unit and $P$ distinguished, the exponent
$\mu$ is read from $p$-divisibility (our content valuation) and $\deg P$ governs
the residual shape (our trailing degree after reduction).

\begin{lemma}[Reduced primitive part is nonzero]\label{lem:pp}
For every $f \in \Z[X]$, $\overline{\pp(f)} \ne 0$.
\end{lemma}
\begin{proof}[Proof sketch]
If $\overline{\pp(f)} = 0$ then $C(p) \mid \pp(f)$, and primitivity
forces $p$ to be a unit in $\Z$, contradicting $p \ge 2$.
\end{proof}

\section{The bridge: additivity of both invariants}

\begin{theorem}[$\mu$-additivity]\label{thm:mu}
For nonzero $f, g \in \Z[X]$, $\muI(f g) = \muI(f) + \muI(g)$.
\end{theorem}
\begin{proof}[Proof sketch]
By Gauss's Lemma $\content(fg) = \content(f)\content(g)$, both nonzero. Apply
$v_p$ and its additivity.
\end{proof}

\begin{theorem}[$\lambda$-additivity]\label{thm:la}
For nonzero $f, g \in \Z[X]$, $\laI(f g) = \laI(f) + \laI(g)$.
\end{theorem}
\begin{proof}[Proof sketch]
The primitive part is multiplicative, and reduction is a homomorphism, so
$\overline{\pp(fg)} = \overline{\pp(f)}\cdot\overline{\pp(g)}$.
By Lemma~\ref{lem:pp} both factors are nonzero in the domain $\Fp[X]$, so their
trailing degrees add.
\end{proof}

\noindent\textbf{Building blocks.}
\begin{center}
\begin{tabular}{lcc}
\toprule
Polynomial & $\muI$ & $\laI$ \\
\midrule
$C(p^{k})$ & $k$ & $0$ \\
$X^{n}$ & $0$ & $n$ \\
$p^{k}\, X^{a}$ & $k$ & $a$ \\
\bottomrule
\end{tabular}
\end{center}

\section{The sharp/flat pair and its twist}

\begin{definition}
For $a, k \in \N$ set $\gtw(a, k) := C(p^{k})\, X^{a} = p^{k} X^{a}$.
\end{definition}

\begin{proposition}\label{prop:g}
$\gtw(a,k) \ne 0$, and $\muI(\gtw(a,k)) = k$, $\laI(\gtw(a,k)) = a$.
\end{proposition}
\begin{proof}[Proof sketch]
Nonvanishing is clear. Apply Theorems~\ref{thm:mu}--\ref{thm:la} and the
building-block table.
\end{proof}

\begin{corollary}[Free $\lambda/\mu$ ratio]
For $a \ne a'$ and any $k$, $\gtw(a,k)$ and $\gtw(a',k)$ have equal
$\mu$-invariant $k$ but distinct $\lambda$-invariants. The ratio $\lambda/\mu$ is
thus not pinned to any fixed constant.
\end{corollary}

\begin{definition}
Fix a common depth $k$ and constants $c_\sharp, c_\flat \in \N$. Define
$\shtw(c_\sharp, k) := \gtw(c_\sharp k, k)$ and
$\fltw(c_\flat, k) := \gtw(c_\flat k, k)$.
\end{definition}

By Proposition~\ref{prop:g}, both have $\mu$-invariant $k$, while
$\laI(\shtw) = c_\sharp k$ and $\laI(\fltw) = c_\flat k$.

Let $f \in \Z[X]$ be nonzero.

\begin{theorem}[$\mu$-symmetry of the twist]
$\muI(f\cdot\shtw(c_\sharp, k)) = \muI(f\cdot\fltw(c_\flat, k)) =
\muI(f) + k$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:mu} and $\muI(\text{twist}) = k$ for both factors.
\end{proof}

\begin{theorem}[$\mu$-proportional $\lambda$-difference]\label{thm:diff}
In $\Z$,
\[
\laI(f\cdot\shtw(c_\sharp, k)) - \laI(f\cdot\fltw(c_\flat, k))
= (c_\sharp - c_\flat)\cdot \muI(\text{twist}),
\]
where $\muI(\text{twist}) = k$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:la}, $\laI(f\cdot\shtw) = \laI(f) + c_\sharp k$ and
$\laI(f\cdot\fltw) = \laI(f) + c_\flat k$; subtract. The statement is placed
in $\Z$ to remain valid whichever constant is larger.
\end{proof}

\begin{theorem}[Sharp non-vanishing]
If $k \ge 1$ (i.e.\ $\mu \ne 0$) and $c_\sharp \ne c_\flat$, then
$\laI(f\cdot\shtw(c_\sharp, k)) \ne \laI(f\cdot\fltw(c_\flat, k))$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:diff} the difference is $(c_\sharp - c_\flat)k$, a product of
nonzero integers, hence nonzero.
\end{proof}

\begin{theorem}[Vanishing when $\mu = 0$]
For any $c_\sharp, c_\flat$,
$\laI(f\cdot\shtw(c_\sharp, 0)) = \laI(f\cdot\fltw(c_\flat, 0))$.
\end{theorem}
\begin{proof}[Proof sketch]
Set $k = 0$ in Theorem~\ref{thm:diff}.
\end{proof}

\subsection{Worked numerical instances}
Take $p = 2$, $k = 3$, $c_\sharp = 5$, $c_\flat = 2$, any nonzero $f$. Then both
twisted $\mu$-invariants equal $\muI(f) + 3$, while the sharp/flat
$\lambda$-difference is $(5 - 2)\cdot 3 = 9$. Also $\gtw(7,3)$ has
$(\lambda, \mu) = (7, 3)$ and $\gtw(4,3)$ has $(4, 3)$: same $\mu$, different
$\lambda$.

\section{Discussion and future work}
The model trades analytic depth for a transparent algebraic skeleton, showing the
$\mu$-proportional correction is forced by multiplicativity of the content
(Gauss's Lemma) and the absence of zero-divisors in $\Fp[X]$. Natural
continuations: (1) pass to $\Lambda = \Zp[[T]]$ via Weierstrass Preparation;
(2) model a genuine $(f^\sharp, f^\flat)$ via the Pollack--Sprung matrix;
(3) define the quadratic twist at the level of Selmer groups / $\Lambda$-modules;
(4) allow a proportionality constant varying with the twisting prime, conjecturing
a depth-weighted linear form $\sum_{\ell \mid D} w(\ell)\mu$; and (5) test against
explicit supersingular curves with non-vanishing $\mu$.

\section{Conclusion}
We built an elementary self-contained model of the Iwasawa $\mu$- and
$\lambda$-invariants on $\Z[X]$, proved both additive under multiplication, and
deduced that under a modeled quadratic twist the sharp and flat $\mu$-invariants
coincide while their $\lambda$-invariants differ by exactly
$(c_\sharp - c_\flat)\mu$ --- nonzero precisely when $\mu \ne 0$ and the channels
differ. This isolates the algebraic heart of the extension of Matsuno's
quadratic-twist comparison to the non-vanishing-$\mu$ regime.

\begin{thebibliography}{9}
\bibitem{Mat} H.\ Matsuno, \emph{Construction of elliptic curves with large
Iwasawa $\lambda$-invariants and large Tate--Shafarevich groups}.
\bibitem{Pol} R.\ Pollack, \emph{On the $p$-adic $L$-function of a modular form at
a supersingular prime}.
\bibitem{Spr} F.\ Sprung, \emph{Iwasawa theory for elliptic curves at
supersingular primes: a pair of main conjectures}.
\bibitem{Iwa} K.\ Iwasawa, \emph{On $\mathbb{Z}_\ell$-extensions of algebraic
number fields}.
\end{thebibliography}

