function decompose(f):
    f <- remove high-degree zero coefficients of f
    c <- 0
    for each coefficient a in f:
        c <- gcd(c, a)
    c <- |c|                      # the content
    prim <- [a / c for a in f]    # exact integer division
    return (c, prim)

